function generate(seed,opts,rnd){
  opts=opts||{};rnd=rnd||prng(seed);
  var cat=opts.category||pick(CATS,rnd);
  var pool=B.filter(function(b){return b.c===cat;});
  var b=pick(pool.length?pool:B,rnd);
  var id=PREFIX+String(seed).padStart(6,'0');
  var rec={id:id,title:b.t,description:b.d,category:b.c,ladder_rank:b.l,
    demo:b.demo,provenance:PROV,last_verified:'2026-10-21',src:SRC,_seed:seed};
  Object.keys(b.f).forEach(function(k){rec[k]=b.f[k];});
  return rec;
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  if(!(new RegExp('^'+PREFIX.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\d{6}$').test(r.id||'')))e.push('id');
  if(typeof r.title!=='string'||!r.title.length)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(CATS.indexOf(r.category)<0)e.push('category');
  if(!(r.ladder_rank>=1&&r.ladder_rank<=3))e.push('ladder_rank');
  if(!r.demo||typeof r.demo.program!=='string'||r.demo.program.length<80)e.push('demo');
  if(r.src!==SRC)e.push('src');
  if(typeof r.provenance!=='string'||!r.provenance.length)e.push('provenance');
  if(typeof r.problem_class==='undefined'||r.problem_class===null||r.problem_class==='')e.push('problem_class');
  if(typeof r.recommended_solver==='undefined'||r.recommended_solver===null||r.recommended_solver==='')e.push('recommended_solver');
  if(typeof r.alternatives==='undefined'||r.alternatives===null||r.alternatives==='')e.push('alternatives');
  if(typeof r.selection_criteria==='undefined'||r.selection_criteria===null||r.selection_criteria==='')e.push('selection_criteria');
  if(typeof r.pitfalls==='undefined'||r.pitfalls===null||r.pitfalls==='')e.push('pitfalls');
  if(typeof r.bench_n==='undefined'||r.bench_n===null||r.bench_n==='')e.push('bench_n');
  return {ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  sample=sample||[];
  var t=String(rec.title||'').toLowerCase();
  for(var i=0;i<sample.length;i++){
    if(String(sample[i].t||sample[i].title||'').toLowerCase()===t)return {ok:false,errors:['drift: title already in archive']};
  }
  return {ok:true,errors:[]};
}
